node --input-type=module <<'NODE'
import fs from 'node:fs';import {validateTracker,sha256} from './scripts/remediation/board.mjs';
const path='docs/remediation/evidence/W05.08/trusted-tracker-290.json',raw=fs.readFileSync(path),expected='24aefdd57b85730293eeffb1f155e69c17a743614af002902f09f9e5dbe588e8';
if(sha256(raw)!==expected) throw new Error('Trusted prior hash mismatch');
const previousTracker=JSON.parse(raw),current=JSON.parse(fs.readFileSync('docs/remediation/tracker.json','utf8'));
const result=validateTracker(current,{rootDir:process.cwd(),previousTracker});
const warningCounts={};for(const w of result.warnings) warningCounts[w.code]=(warningCounts[w.code]||0)+1;
console.log(JSON.stringify({at:new Date().toISOString(),priorPath:path,priorSha256:sha256(raw),priorJournal:previousTracker.journal.length,currentJournal:current.journal.length,trackerSha256:sha256(fs.readFileSync('docs/remediation/tracker.json')),ok:result.ok,errors:result.errors,warningCounts,currentTaskWarnings:result.warnings.filter(w=>JSON.stringify(w).includes('W05.08')),currentTask:{state:current.tasks.find(t=>t.id==='W05.08').state,artifact:current.tasks.find(t=>t.id==='W05.08').artifact.digest}},null,2));
if(!result.ok) process.exitCode=1;
NODE
